Create Procedure GuiasPenDetalle as Select mc.WAREHOUSE_ID,mc.NUMBER_DOCUMENT,mc.DATE_DOCUMENT,mc.CUSTOMER_NAME,mc.TRANS_ID,mc.DOC_ID_REF,mc.NUM_ID_REF,mc.STATUS_GUIA,mc.CUSTOMER_ID , mc.VAT_REGISTRATION, mc.DOCUMENT_ID, md.PART_ID, md.QTY, md.PART_DESCRIPTION, md.UNIT_PART from [IVM].dbo.WAREHOUSE_TRANS mc inner join [IVM].dbo.WAREHOUSE_TRANS_LINE md  on mc.WAREHOUSE_ID=md.WAREHOUSE_ID and mc.DOCUMENT_ID=md.DOCUMENT_ID and mc.NUMBER_DOCUMENT=md.NUMBER_DOCUMENT  where mc.DOCUMENT_ID = 'GS' AND (mc.TRANS_ID = 'GV') AND (mc.TYPE_GUIA = 'GV' ) AND mc.STATUS_GUIA NOT IN ('F','A') and mc.CUSTOMER_ID>='100' and mc.CUSTOMER_ID<='20552908491' and mc.DATE_DOCUMENT>='01/01/2013' and mc.DATE_DOCUMENT<='31/01/2014' group by mc.WAREHOUSE_ID,mc.NUMBER_DOCUMENT,mc.DATE_DOCUMENT,mc.CUSTOMER_NAME,mc.TRANS_ID,mc.DOC_ID_REF,mc.NUM_ID_REF,mc.STATUS_GUIA,mc.CUSTOMER_ID , mc.VAT_REGISTRATION, mc.DOCUMENT_ID,md.PART_ID, md.QTY, md.PART_DESCRIPTION, md.UNIT_PART